import { ChangeDetectionStrategy, Component } from '@angular/core';
import { SemiFinished } from '../../pages/semi-finished/semi-finished';
import { SemiFinishedService } from '../../services/semi-finished-service';
import { FormGroup, FormBuilder, Validators, ReactiveFormsModule } from '@angular/forms';
import { CommonModule } from '@angular/common';
import { Router } from '@angular/router';

@Component({
  selector: 'app-add-semi-finished',
  imports: [CommonModule, ReactiveFormsModule],
  templateUrl: './add-semi-finished.html',
  styleUrl: './add-semi-finished.css',
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class AddSemiFinished {
 semiFinishedForm: FormGroup;

constructor(private service: SemiFinishedService, private fb: FormBuilder, private router: Router) {
  this.semiFinishedForm = this.fb.group({
    name : ['', Validators.required],
    price : [''],
  })
}
  onSubmit() {
    console.log('Submit clicked');
    if (this.semiFinishedForm.invalid) {
      this.semiFinishedForm.markAllAsTouched();
      return;
    }

    console.log('Form value:', this.semiFinishedForm.value);

    this.service.addProduct(this.semiFinishedForm.value).subscribe({
      next: () => {
        alert('✅ Semi Finished created successfully');
        this.resetForm();
        this.router.navigate(['/semi-finished'])
      },
      error: (err) => {
        console.error('❌ Upload failed', err);
        alert(err.error?.message || 'Upload failed. Please try again.');
      }
    });
  }

  private resetForm() {
    this.semiFinishedForm.reset();
    
  }
}
